int main() {
    int number = 472;

    // Write your code here
    return 0;
}

coding.solution:
#include <iostream>
using namespace std;

int main() {
    int number = 472;

    int hundreds = number / 100;
    int tens = (number / 10) % 10;
    int ones = number % 10;

    cout << hundreds + tens + ones;
    return 0;
}
